function limparCaracteresCPF(cpf) {
    let cpf_clean = String(cpf).replace(/[^\d]/g, '');
    let validacao = validarCPF(cpf_clean);

    if (validacao) {
        return cpf_clean;
    } else {
        return false;
    }
}

function validarCPF(strCPF) {
    var Soma = 0;
    var Resto;

    if (strCPF.length !== 11)
        return false;

    if ([
        '00000000000',
        '11111111111',
        '22222222222',
        '33333333333',
        '44444444444',
        '55555555555',
        '66666666666',
        '77777777777',
        '88888888888',
        '99999999999',
    ].indexOf(strCPF) !== -1)
        return false;

    for (var i = 1; i <= 9; i++)
        Soma = Soma + parseInt(strCPF.substring(i - 1, i)) * (11 - i);

    Resto = (Soma * 10) % 11;

    if (Resto === 10 || Resto === 11)
        Resto = 0;

    if (Resto !== parseInt(strCPF.substring(9, 10)))
        return false;

    Soma = 0;

    for (var i = 1; i <= 10; i++)
        Soma = Soma + parseInt(strCPF.substring(i - 1, i)) * (12 - i);

    Resto = (Soma * 10) % 11;

    if (Resto === 10 || Resto === 11)
        Resto = 0;

    if (Resto !== parseInt(strCPF.substring(10, 11)))
        return false;

    return true;
}

return limparCaracteresCPF({{CPF_INPUT_CONSULTA}});

