function validaDataCompleta(dataFormatada) {
    const dataPadrao = /^(\d{2})\/(\d{2})\/(\d{4})$/;

    if (!dataPadrao.test(dataFormatada)) return false;

    const partesData = dataFormatada.split("/");
    const dia = parseInt(partesData[0], 10);
    const mes = parseInt(partesData[1], 10);
    const ano = parseInt(partesData[2], 10);

    if (ano < 1900) return false;
    if (mes <= 0 || mes > 12) return false;

    const diasDoMes = new Date(ano, mes, 0).getDate();
    if (dia <= 0 || dia > diasDoMes) return false;

    return true;
}

function validarData(inputData) {

    let dataNumerica;
    if (typeof inputData === 'number') {
        dataNumerica = inputData.toString();
    } else if (typeof inputData === 'string') {
        dataNumerica = inputData.replace(/\D/g, '');
    } else {
        return false;
    }

    const ano = parseInt(dataNumerica.substring(4, 8));
    const mes = parseInt(dataNumerica.substring(2, 4)) - 1;
    const dia = parseInt(dataNumerica.substring(0, 2));

    const dataFormatada = ("0" + dia).slice(-2) + "/" + ("0" + (mes + 1)).slice(-2) + "/" + ano;

    if (!validaDataCompleta(dataFormatada)) {
        return false;
    } else {
        return dataFormatada
    }
}

